import{_ as s,c as t,o as r,j as e,a as o}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"简介","description":"帛书易 - 简介","frontmatter":{"title":"简介","description":"帛书易 - 简介"},"headers":[],"relativePath":"zh/classics/boshuyi/001.md","filePath":"zh/classics/boshuyi/001.md"}'),i={name:"zh/classics/boshuyi/001.md"};function c(n,a,l,d,p,h){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"简介",tabindex:"-1"},[o("简介 "),e("a",{class:"header-anchor",href:"#简介","aria-label":"Permalink to “简介”"},"​")],-1),e("p",null,"《帛书易》简介 ​帛书《周易》1973年12月出土于湖南长沙马王堆汉墓3号，与其它27种帛书一起出土。原盛于一漆盒内。关于帛书《周易》的抄录年代，专家们的判断是约在西汉文帝初年，即大约公元前180年至170年间。这意味着帛书《周易》的版本可能是基于更早的竹简本进行抄录的，其原始内容的撰写时间应该更为久远。相较于通行版本，帛书《周易》有其独特之处。首先，其卦序与传世本有所不同。其次，一些卦名也存在差异，这些差异可能源自通假字的使用。此外，帛书《周易》还包括了《易传》部分，例如《二三子间》上下篇以及《系辞》、《易之义》、《要》、《缪和》、《昭力》等篇章。内容与结构：帛书《周易》的内容主要分为“经”和“传”两部分。经部分主要是六十四卦的卦形符号与卦爻辞，包括阴爻和阳爻。这些卦形符号和卦爻辞是《周易》的核心，用于描述和解释自然现象、人事变化以及道德准则。传部分是对经文的阐释和发挥，包括《彖传》上下、《象传》上下、《文言》、《系辞传》上下、《说卦传》、《序卦传》、《杂卦传》共计7种10篇。这些传文对于理解经文起到了重要的辅助作用，帮助读者深入领会《周易》的哲学思想和智慧。编排与特点：帛书《周易》的编排经过精心考虑。它以经文在最前面，随后分说经文，再通论大义，又于论说外记事，最后是传《易》经师的言论。这种编排方式使得整部《周易》既有系统性，又有层次性，便于读者阅读和理解。此外，帛书《周易》以键、根、赣、辰、川、夺、罗、筭八个卦为基本卦，将六十四卦分为八组。每组中分别以固定的一卦为上卦，然后取与之相同的卦为下卦，组成一个六爻的卦。这种分组方式使得卦与卦之间的关系更加紧密，也更容易揭示其内在的逻辑和规律。文化价值：帛书《周易》的出土为我们提供了研究古代易学文化的重要资料。它不仅揭示了古代人们对宇宙、人生、精神、物质等问题的探求及演绎，也反映了古代社会的哲学思想和智慧。因此，帛书《周易》在学术研究和文化传承方面都具有极高的价值。需要注意的是，尽管帛书《周易》与通行版本在某些方面存在差异，但这并不意味着通行版本不如出土版本真实可靠。两者各有其特点和价值，我们应该以客观、理性的态度对待它们，并结合其他相关资料进行综合研究和分析。总的来说，帛书《周易》是一部珍贵的历史文献，它为我们了解古代易学文化提供了重要的线索和依据。通过深入研究帛书《周易》，我们可以更好地领略古代人们的智慧和哲学思想，也可以为现代社会的发展和进步提供有益的借鉴和启示。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
